def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    result = []
    for part in parts:
        # Extract leading digits
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            result.append(int(num_str))
        else:
            result.append(0)
    return tuple(result)

