def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        order = []
        maxsize_local = maxsize
        typed_local = typed

        def make_key(args, kwargs):
            if typed_local:
                key = args
                if kwargs:
                    key += (None,)
                    key += tuple(sorted(kwargs.items()))
            else:
                key = args
                if kwargs:
                    key += (None,)
                    key += tuple(sorted(kwargs.items()))
            return key

        def wrapper_func(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move to end of order (most recently used)
                order.remove(key)
                order.append(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                order.append(key)
                if maxsize_local is not None and len(cache) > maxsize_local:
                    oldest = order.pop(0)
                    del cache[oldest]
                return result

        wrapper_func.cache_info = lambda: {'hits': 0, 'misses': 0, 'maxsize': maxsize_local, 'currsize': len(cache)}
        wrapper_func.cache_clear = lambda: (cache.clear(), order.clear())
        return wrapper_func
    return wrapper

