def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        if not self._edges:
            return
        if len(coord) != len(self._edges) - 1:
            raise ValueError("Coordinate dimension mismatch")
        for i, c in enumerate(coord):
            if c < self._edges[i] or c >= self._edges[i + 1]:
                return
        index = []
        for i, c in enumerate(coord):
            bin_index = int((c - self._edges[i]) / (self._edges[i + 1] - self._edges[i]) * self._nbins[i])
            if bin_index >= self._nbins[i]:
                bin_index = self._nbins[i] - 1
            index.append(bin_index)
        self._hist[tuple(index)] += weight

