def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Check that prior is an InventoryValidator object
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator object")

        # Check that prior's version is less than or equal to self's version
        if prior.version > self.version:
            raise ValueError("prior version must be less than or equal to current version")

        # Check that all items in prior are present in self
        for item_id, item in prior.items.items():
            if item_id not in self.items:
                raise ValueError(f"Item {item_id} in prior version not found in current version")
            # Check that the item in self is a valid update of the item in prior
            self_item = self.items[item_id]
            if not self_item.is_valid_update_of(item):
                raise ValueError(f"Item {item_id} in current version is not a valid update of prior version")

        # Check that no items in self are invalid updates of items in prior
        for item_id, item in self.items.items():
            if item_id in prior.items:
                prior_item = prior.items[item_id]
                if not item.is_valid_update_of(prior_item):
                    raise ValueError(f"Item {item_id} in current version is not a valid update of prior version")

        # If all checks pass, return True
        return True

