def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        for file_path, checksum in fixity.items():
            if file_path not in manifest_files:
                raise ValueError(f"File {file_path} in fixity block is not in the manifest")
            if not isinstance(checksum, str):
                raise ValueError(f"Checksum for {file_path} must be a string")
            if len(checksum) != 64:
                raise ValueError(f"Checksum for {file_path} must be a 64-character SHA-256 hash")
            if not all(c in '0123456789abcdef' for c in checksum.lower()):
                raise ValueError(f"Checksum for {file_path} must be a valid hexadecimal string")

