    import os
    import json
    import logging
    import yaml
    import re

    config_dict = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                content = f.read()

            # Resolve environment variables if requested
            if resolve_env:
                def replace_env(match):
                    var_name = match.group(1)
                    return os.environ.get(var_name, match.group(0))
                content = re.sub(r'\$\{(\w+)\}', replace_env, content)

            # Determine file type by extension
            if filename.endswith('.json'):
                config = json.loads(content)
            elif filename.endswith(('.yaml', '.yml')):
                config = yaml.safe_load(content)
            else:
                # Default to YAML for unknown extensions
                config = yaml.safe_load(content)

            # Apply overrides if provided
            if overrides:
                if isinstance(overrides, dict):
                    # Deep merge overrides into config
                    def deep_merge(base, override):
                        for key, value in override.items():
                            if key in base and isinstance(base[key], dict) and isinstance(value, dict):
                                deep_merge(base[key], value)
                            else:
                                base[key] = value
                        return base
                    config = deep_merge(config, overrides)
                else:
                    # If overrides is not a dict, just use it as is? Or ignore?
                    # The docstring says "overrides=None", implying it's optional.
                    # If provided, it should probably be a dict.
                    pass

            config_dict[filename] = config
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Failed to load configuration file {filename}: {str(e)}",
                args=None,
                exc_info=None
            )
            error_records.append(record)

    return config_dict, error_records

