    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # Check if candidate is a subclass of iface or is iface itself
    if not issubclass(candidate, iface):
        if tentative:
            return False
        else:
            raise TypeError(f"{candidate} does not provide {iface}")

    # If tentative, just return True if it's a subclass
    if tentative:
        return True

    # For non-tentative, we might want to check for abstract methods
    # Check if candidate has all the abstract methods of iface
    if hasattr(iface, '__abstractmethods__'):
        abstract_methods = iface.__abstractmethods__
        for method in abstract_methods:
            if not hasattr(candidate, method):
                raise TypeError(f"{candidate} does not implement abstract method {method} of {iface}")

    return True

