    """
    Try to identify whether this is a Matrix request
    """
    # Check if the request has a path that starts with /_matrix
    if hasattr(request, 'path') and request.path.startswith('/_matrix'):
        return True
    # Check if the request has a header indicating Matrix
    if hasattr(request, 'headers'):
        headers = request.headers
        if 'X-Matrix-Request' in headers:
