def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        # Check if it looks like a webfinger JSON response
        if isinstance(data, dict) and 'links' in data:
            return data
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
        # XRD root element is typically 'XRD'
        if root.tag == 'XRD':
            result = {}
            # Extract subject
            subject_elem = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject')
            if subject_elem is not None:
                result['subject'] = subject_elem.text

            # Extract aliases
            aliases = []
            for alias_elem in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias'):
                if alias_elem.text:
                    aliases.append(alias_elem.text)
            if aliases:
                result['aliases'] = aliases

            # Extract links
            links = []
            for link_elem in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                link = {}
                rel = link_elem.get('rel')
                if rel:
                    link['rel'] = rel
                href = link_elem.get('href')
                if href:
                    link['href'] = href
                typ = link_elem.get('type')
                if typ:
                    link['type'] = typ
                links.append(link)
            if links:
                result['links'] = links

            return result
    except ET.ParseError:
        pass

    # If neither format could be parsed, return empty dict or raise
    return {}

